def minTaps(n, ranges):
    far = list(range(n + 1))  # far[x] = furthest right end of a stretch starting at x (or before)
    for i, r in enumerate(ranges):
        left = max(0, i - r)
        right = min(n, i + r)
        if right > far[left]:
            far[left] = right
    taps = 0
    cur_end = 0
    furthest = 0
    for x in range(n):
        if far[x] > furthest:
            furthest = far[x]
        if x == cur_end:
            if furthest <= cur_end:
                return -1
            taps += 1
            cur_end = furthest
            if cur_end >= n:
                break
    return taps
